INSERT INTO questions (id, skill_id, topic, question_type, difficulty, question_text, explanation, active) VALUES (1181, 22, 'Syllogisms', 'SINGLE_CHOICE', 'BEGINNER', 'All cats are animals. All animals are living beings. Conclusion: All cats are living beings.', 'Both premises chain together, so every cat is a living being.', TRUE);
