INSERT INTO questions (id, skill_id, topic, question_type, difficulty, question_text, explanation, active) VALUES (1210, 18, 'Testing Fundamentals', 'SINGLE_CHOICE', 'BEGINNER', 'What is the main purpose of software testing?', 'Testing provides information about quality. It cannot prove that no defects exist.', TRUE);
